class TrackBlasThreads:
    def track_blas_threads(self):
        infos = threadpool_info()
        if not infos:
            return 1
        return max(info["num_threads"] for info in infos)

    def setup(self):
        # trigger BLAS initialization so threadpool_info sees the pools
        L = block_laplacian(200, 1)
        expm(-L)

